  bool has_workspace = true;
  uint32_t non_list_len = 0;
  OpMC2Def op_mc2;
  FormatCheckOption format_mode = FormatCheckOption::MAX;
  bool enable_fall_back = false;
};
}  // namespace ops

#endif

